import { countWords } from './countWords';

describe('countWords', () => {
  it('counts single words', () => {
    expect(countWords('hello')).toEqual({ hello: 1 });
  });

  it('counts repeated words case-insensitively', () => {
    expect(countWords('Hello hello HELLO')).toEqual({ hello: 3 });
  });

  it('ignores punctuation', () => {
    expect(countWords('Hello, world!')).toEqual({ hello: 1, world: 1 });
  });

  it('returns empty object for empty string', () => {
    expect(countWords('')).toEqual({});
  });

  it('counts multiple different words', () => {
    const result = countWords('the cat sat on the mat');
    expect(result).toEqual({ the: 2, cat: 1, sat: 1, on: 1, mat: 1 });
  });
});

import { celsiusToFahrenheit, fahrenheitToCelsius, celsiusToKelvin } from './temperatureConverter';

describe('Temperature Converter', () => {
  it('converts 0°C to 32°F', () => {
    expect(celsiusToFahrenheit(0)).toBe(32);
  });

  it('converts 100°C to 212°F', () => {
    expect(celsiusToFahrenheit(100)).toBe(212);
  });

  it('converts 98.6°F to 37°C', () => {
    expect(fahrenheitToCelsius(98.6)).toBe(37);
  });

  it('converts 0°C to 273.15K', () => {
    expect(celsiusToKelvin(0)).toBe(273.15);
  });

  it('throws an error for temperature below absolute zero', () => {
    expect(() => celsiusToFahrenheit(-300)).toThrow();
  });
});

import { evaluate } from './expression-parser';

describe('ExpressionParser', () => {
  it('respects operator precedence', () => {
    expect(evaluate('2 + 3 * 4')).toBe(14);
    expect(evaluate('10 - 6 / 2')).toBe(7);
  });

  it('handles parentheses', () => {
    expect(evaluate('(2 + 3) * 4')).toBe(20);
    expect(evaluate('((1 + 2)) * (3 + 4)')).toBe(21);
  });

  it('resolves variables from an environment map', () => {
    expect(evaluate('x * 2 + y', { x: 5, y: 3 })).toBe(13);
  });

  it('applies unary minus to expressions', () => {
    expect(evaluate('-x + 10', { x: 3 })).toBe(7);
    expect(evaluate('-(x + 1) * 2', { x: 4 })).toBe(-10);
  });

  it('treats exponentiation as right-associative', () => {
    expect(evaluate('2 ^ 3 ^ 2')).toBe(512);
  });

  it('throws on malformed or incomplete expressions', () => {
    expect(() => evaluate('2 +')).toThrow();
    expect(() => evaluate('(2 + 3')).toThrow();
    expect(() => evaluate('x + 1')).toThrow(/unknown variable/i);
    expect(() => evaluate('10 / 0')).toThrow(/division by zero/i);
  });
});

import { evaluate } from './expressionParser';

// Basic arithmetic with precedence
expect(evaluate('2 + 3 * 4')).toBe(14);
expect(evaluate('(2 + 3) * 4')).toBe(20);

// Variables
expect(evaluate('x * 2 + y', { x: 5, y: 3 })).toBe(13);

// Unary minus
expect(evaluate('-x + 10', { x: 4 })).toBe(6);
expect(evaluate('-(x + 1) * 2', { x: 2 })).toBe(-6);

// Error cases
expect(() => evaluate('2 + (3 * 4')).toThrow(SyntaxError);
expect(() => evaluate('x + 1', {})).toThrow(ReferenceError);

