class ShoppingCartTest {

    @Test
    void addingItemsAccumulatesTotal() {
        ShoppingCart cart = new ShoppingCart();
        cart.addItem("Apple", 1.50);
        cart.addItem("Bread", 2.00);
        assertEquals(3.50, cart.getTotal(), 0.001);
    }

    @Test
    void fiveOrMoreItemsApplyTwentyPercentDiscount() {
        ShoppingCart cart = new ShoppingCart();
        cart.addItem("A", 10.0);
        cart.addItem("B", 10.0);
        cart.addItem("C", 10.0);
        cart.addItem("D", 10.0);
        cart.addItem("E", 10.0);
        assertEquals(40.0, cart.getTotal(), 0.001); // 50.0 - 20%
    }

    @Test
    void invalidPromoCodeThrowsException() {
        ShoppingCart cart = new ShoppingCart();
        cart.addItem("Widget", 20.0);
        assertThrows(IllegalArgumentException.class, () -> cart.applyPromoCode("FAKE99"));
    }
}

import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;

class BankAccountTest {

    @Test
    void depositIncreasesBalance() {
        BankAccount account = new BankAccount();
        account.deposit(1000.00);
        assertEquals(1000.00, account.getBalance(), 0.001);
    }

    @Test
    void withdrawalDecreasesBalance() {
        BankAccount account = new BankAccount();
        account.deposit(1000.00);
        account.withdraw(300.00);
        assertEquals(700.00, account.getBalance(), 0.001);
    }

    @Test
    void statementFormatsCorrectly() {
        BankAccount account = new BankAccount();
        account.deposit(500.00);
        account.withdraw(200.00);
        String statement = account.getStatement();
        assertTrue(statement.contains("DEPOSIT 500.00 | Balance: 500.00"));
        assertTrue(statement.contains("WITHDRAWAL 200.00 | Balance: 300.00"));
    }

    @Test
    void insufficientFundsThrowsException() {
        BankAccount account = new BankAccount();
        account.deposit(100.00);
        assertThrows(IllegalStateException.class, () -> account.withdraw(200.00));
    }

    @Test
    void totalDepositedAndWithdrawnTrackedSeparately() {
        BankAccount account = new BankAccount();
        account.deposit(1000.00);
        account.deposit(500.00);
        account.withdraw(300.00);
        assertEquals(1500.00, account.getTotalDeposited(), 0.001);
        assertEquals(300.00, account.getTotalWithdrawn(), 0.001);
    }
}

