describe('EmailValidator', () => {
  const validator = new EmailValidator();

  test('should validate a correct email', () => {
    expect(validator.isValid('john.doe@example.com')).toBe(true);
  });

  test('should reject email without @ symbol', () => {
    expect(validator.isValid('johndoe.example.com')).toBe(false);
  });

  test('should reject email with invalid domain', () => {
    expect(validator.isValid('john@domain')).toBe(false);
  });

  test('should normalize email to lowercase', () => {
    expect(validator.normalize('JOHN@EXAMPLE.COM')).toBe('john@example.com');
  });
});

it('should evaluate expressions with precedence, variables, and functions', () => {
  const evaluator = new ExpressionEvaluator();

  expect(evaluator.evaluate('2 + 3 * 4')).toBe(14);
  expect(evaluator.evaluate('(2 + 3) * 4')).toBe(20);

  const ctx = { x: 5, y: 3 };
  expect(evaluator.evaluate('x + y', ctx)).toBe(8);

  evaluator.defineFunction('square', ['n'], 'n * n');
  expect(evaluator.evaluate('square(4)')).toBe(16);

  expect(() => evaluator.evaluate('z + 1')).toThrow('Undefined variable: z');
  expect(() => evaluator.evaluate('10 / 0')).toThrow('Division by zero');
});

func TestReverseVowels(t *testing.T) {
    tests := []struct {
        input    string
        expected string
    }{
        {"hello", "holle"},
        {"aeiou", "uoiea"},
        {"bcdfg", "bcdfg"},
        {"a", "a"},
    }
    for _, tt := range tests {
        if got := ReverseVowels(tt.input); got != tt.expected {
            t.Errorf("ReverseVowels(%q) = %q, want %q", tt.input, got, tt.expected)
        }
    }
}

func TestWordFrequency(t *testing.T) {
    result := WordFrequency("hello world hello")
    if result["hello"] != 2 {
        t.Errorf("expected 2 'hello', got %d", result["hello"])
    }
    if result["world"] != 1 {
        t.Errorf("expected 1 'world', got %d", result["world"])
    }
    if len(result) != 2 {
        t.Errorf("expected 2 unique words, got %d", len(result))
    }
}

